     *   value will be `0` if `auto_scale` is set to `false`.
     */
    fun kubernetesUpdateNodePool(
        clientConfig: ClientConfig,
        request: Kubernetes.KubernetesUpdateNodePoolRequest,
        options: RequestOptions? = null,
    ): NodePoolUpdate {
