                    operationId = "kubernetesUpdateNodePool",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors =
                        mapOf(
                            "401" to Error2::class.java,
                            "404" to Error2::class.java,
                            "429" to Error2::class.java,
                            "500" to Error2::class.java,
                            "default" to Error2::class.java,
